import random
import pytix

def generate_ticket():
    return pytix.generate_ticket()

def main():
    print("Welcome to 'Mystery Box'!")
    print("You have 5 attempts to guess the 3-digit code.")
    code = random.randint(100, 999)
    attempts = 5

    while attempts > 0:
        try:
            guess = int(input("Enter your guess: "))
            if guess < code:
                print("Too Low")
            elif guess > code:
                print("Too High")
            else:
                print("Correct!")
                print("Generated Ticket:", generate_ticket())
                break
            attempts -= 1
        except ValueError:
            print("Please enter a valid 3-digit number.")

    if attempts == 0:
        print("Game Over! The code was", code)
        print("Generated Ticket on Loss:", generate_ticket())

if __name__ == "__main__":
    main()
